const ctx = $('Préparer la requête').first().json;
const res = $input.first().json;
const text = (res.candidates?.[0]?.content?.parts ?? []).map((p) => p.text ?? '').join('');

let out;
try {
  out = JSON.parse(text);
} catch {
  out = { diagnostic_markdown: text, note_interne: 'Réponse non structurée : relire attentivement avant envoi.' };
}
if (!out.diagnostic_markdown) throw new Error('Diagnostic vide : vérifier la réponse du modèle');

const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const inline = (s) => esc(s).replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>').replace(/(^|[^*])\*([^*]+)\*/g, '$1<em>$2</em>');

function md(src) {
  const html = [];
  let list = null;
  const close = () => { if (list) { html.push(`</${list}>`); list = null; } };
  for (const raw of String(src).split('\n')) {
    const line = raw.trimEnd();
    let m;
    if (!line.trim()) { close(); continue; }
    if ((m = line.match(/^(#{1,3})\s+(.*)$/))) {
      close();
      const lvl = m[1].length;
      const size = { 1: '24px', 2: '19px', 3: '16px' }[lvl];
      html.push(`<h${lvl} style="margin:22px 0 8px;font:700 ${size}/1.25 Helvetica,Arial,sans-serif;color:#1a1410;">${inline(m[2])}</h${lvl}>`);
    } else if ((m = line.match(/^\s*[-*]\s+(.*)$/))) {
      if (list !== 'ul') { close(); html.push('<ul style="margin:8px 0;padding-left:22px;">'); list = 'ul'; }
      html.push(`<li style="margin:0 0 6px;">${inline(m[1])}</li>`);
    } else if ((m = line.match(/^\s*\d+[.)]\s+(.*)$/))) {
      if (list !== 'ol') { close(); html.push('<ol style="margin:8px 0;padding-left:22px;">'); list = 'ol'; }
      html.push(`<li style="margin:0 0 6px;">${inline(m[1])}</li>`);
    } else {
      close();
      html.push(`<p style="margin:0 0 12px;">${inline(line)}</p>`);
    }
  }
  close();
  return html.join('\n');
}

const { name, email, lang } = ctx.meta;
const note = esc(out.note_interne || '').replace(/\n/g, '<br>');
const html = `<!doctype html><html><body style="margin:0;padding:24px 12px;background:#f4ece2;">
<div style="max-width:640px;margin:0 auto;font:16px/1.6 Helvetica,Arial,sans-serif;color:#2a211b;">
  <div style="background:#1a1410;color:#f1e8de;padding:14px 20px;border-radius:14px 14px 0 0;font-weight:700;">À relire avant envoi : ${esc(name || 'client')} (${esc(email)}) · ${lang.toUpperCase()}</div>
  <div style="background:#fff3cd;border:1px solid #e8b75a;padding:14px 20px;font-size:14px;"><strong>Note interne (ne pas transmettre)</strong><br>${note}</div>
  <div style="background:#fffaf4;padding:24px 28px;border-radius:0 0 14px 14px;">${md(out.diagnostic_markdown)}</div>
  <p style="font-size:12px;color:#7a6a5c;text-align:center;">Répondez à cet e-mail pour écrire directement au client. Commande n° ${esc(ctx.meta.orderId)}.</p>
</div></body></html>`;

return [{ json: { payload: {
  from: ctx.config.MAIL_FROM,
  to: [ctx.config.OWNER_EMAIL],
  reply_to: email || undefined,
  subject: `Diagnostic à relire : ${name || email}`,
  html,
} } }];
